<?php
declare(strict_types=1);header('Cache-Control: no-store');require_once __DIR__.'/../src/auth.php';require_once __DIR__.'/../src/permissions.php';$user=auth_require_login();require_role('ADMIN');$today=date('Y-m-d');$from=date('Y-m-01');?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>D1 Änderungsliste</title><link rel="stylesheet" href="app.css"><style>.hidden{display:none}.d1-actions{display:flex;gap:.5rem;flex-wrap:wrap}.status-local_change_pending{background:#fff7ed}.status-in_sync{background:#f0fdf4}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body>
<div class="card"><div class="row"><strong>Angemeldet: <?=htmlspecialchars((string)$user['display_name'],ENT_QUOTES,'UTF-8')?></strong><a class="button secondary" href="vf_export_journal.php">Exportjournal</a><a class="button secondary" href="dashboard.php">Dashboard</a></div></div>
<h1>D1 Änderungsliste</h1><p class="info">Vergleicht den aktuellen LSZJ-Payload mit dem zuletzt erfolgreich gesendeten Payload. D1 schreibt nicht nach Vereinsflieger.</p>
<div class="card"><div class="row"><label>Von <input id="from" type="date" value="<?=$from?>"></label><label>Bis <input id="to" type="date" value="<?=$today?>"></label><label>Status <select id="status"><option value="all">Alle</option><option value="in_sync">Synchron</option><option value="local_change_pending">Lokal geändert</option><option value="blocked_person_resolution">Person blockiert</option><option value="blocked_payload_generation">Payload blockiert</option><option value="reconciliation_required">Abstimmung</option></select></label><label><input id="changedOnly" type="checkbox"> Nur Handlungsbedarf</label><button id="load">Liste laden</button></div><div class="d1-actions"><button id="checkSelected" disabled>Ausgewählte neu prüfen</button><button id="selectAll" disabled>Alle sichtbaren auswählen</button></div></div>
<div id="msg" class="card">Noch nicht geladen.</div><div id="out" class="card hidden"></div>
<script>'use strict';const csrf=<?=json_encode(csrf_token())?>,out=document.getElementById('out'),msg=document.getElementById('msg');let busy=false,items=[];const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function api(body){const r=await fetch('api_vf_export_changes.php?v=d1',{method:'POST',cache:'no-store',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,csrf_token:csrf})});const t=await r.text();let d;try{d=JSON.parse(t)}catch(x){throw new Error(t.slice(0,250))}if(!r.ok||!d.ok)throw new Error(d.error||'HTTP '+r.status);return d}function ids(){return Array.from(document.querySelectorAll('.pick:checked')).map(x=>+x.value)}function controls(){checkSelected.disabled=busy||ids().length===0;selectAll.disabled=busy||items.length===0}function effective(i){return i.latest_check_status||i.vf_sync_status||'in_sync'}function table(){return `<table><tr><th>Auswahl</th><th>Flug</th><th>VF</th><th>Status</th><th>Prüfung</th><th>Aktionen</th></tr>${items.map(i=>{const s=effective(i);return `<tr class="status-${e(s)}"><td><input class="pick" type="checkbox" value="${i.accounting_entry_id}"></td><td><strong>${e(i.callsign)}</strong><br>${e(i.pilot_name)}<br>${e(i.departure_time)}<br><small>LSZJ ${i.accounting_entry_id}, Op ${i.operation_id}</small></td><td>${e(i.vf_flid)}<br><small>${e(i.succeeded_at)}</small></td><td>${e(s)}<br>${i.difference_count??0} Unterschiede<br>${e(i.highest_risk||'')}</td><td>${e(i.checked_at||'noch nicht geprüft')}<br>${e(i.vf_local_change_reason||'')}</td><td><button class="one" data-id="${i.accounting_entry_id}">Neu prüfen</button> <button class="details" data-id="${i.accounting_entry_id}">Details</button> <a class="button secondary" href="exported_flight_correction.php?accounting_entry_id=${i.accounting_entry_id}">Admin-Korrektur</a></td></tr>`}).join('')}</table>`}async function loadList(){busy=true;controls();msg.textContent='Liste wird geladen …';try{const d=await api({action:'list',from:from.value,to:to.value,status:status.value,changed_only:changedOnly.checked,limit:200});items=d.items;out.innerHTML=table();out.classList.remove('hidden');msg.textContent=`${items.length} exportierte Flüge gefunden.`;document.querySelectorAll('.pick').forEach(x=>x.onchange=controls);document.querySelectorAll('.one').forEach(x=>x.onclick=()=>checkOne(+x.dataset.id));document.querySelectorAll('.details').forEach(x=>x.onclick=()=>details(+x.dataset.id))}catch(x){msg.innerHTML='<div class="warnbox">'+e(x.message)+'</div>'}finally{busy=false;controls()}}async function checkOne(id){busy=true;controls();msg.textContent=`LSZJ ${id} wird geprüft …`;try{const d=await api({action:'check_one',accounting_entry_id:id});msg.innerHTML='<div class="okbox">Prüfung '+e(d.result.check_status)+', '+e(d.result.difference_count)+' Unterschiede.</div>';await loadList()}catch(x){msg.innerHTML='<div class="warnbox">'+e(x.message)+'</div>';busy=false;controls()}}async function checkMany(){const a=ids();if(!a.length)return;busy=true;controls();msg.textContent=`${a.length} Flüge werden einzeln geprüft …`;try{const d=await api({action:'check_many',accounting_entry_ids:a});msg.innerHTML='<div class="okbox">'+e(JSON.stringify(d.counts))+'</div>';await loadList()}catch(x){msg.innerHTML='<div class="warnbox">'+e(x.message)+'</div>';busy=false;controls()}}async function details(id){try{const d=await api({action:'details',accounting_entry_id:id});const r=d.result;if(!r){msg.textContent='Noch keine Prüfung vorhanden.';return}msg.innerHTML=`<h2>Details LSZJ ${id}</h2><p>Status: ${e(r.check_status)}, Risiko: ${e(r.highest_risk||'-')}</p><details open><summary>Unterschiede</summary><pre>${e(JSON.stringify(r.differences,null,2))}</pre></details><details><summary>Aktueller Payload</summary><pre>${e(JSON.stringify(r.current_payload,null,2))}</pre></details>`}catch(x){msg.innerHTML='<div class="warnbox">'+e(x.message)+'</div>'}}load.onclick=loadList;checkSelected.onclick=checkMany;selectAll.onclick=()=>{document.querySelectorAll('.pick').forEach(x=>x.checked=true);controls()};controls();</script></body></html>
